{
  "items": [
    {
      "index": 1,
      "scene": "公共交通出行",
      "angle": "公交车到站后无人上下车，求车上现有人数（涉及加0或减0）",
      "combo": "none"
    },
    {
      "index": 2,
      "scene": "校园活动组织",
      "angle": "已知两组学生总数和其中一组人数，利用8或9的组成求另一组人数",
      "combo": "none"
    },
    {
      "index": 3,
      "scene": "数学益智游戏",
      "angle": "在数字接龙游戏中，根据前一个数利用10的组成推算下一个数",
      "combo": "none"
    },
    {
      "index": 4,
      "scene": "家务劳动调查",
      "angle": "记录三天做家务的次数，通过连加计算这三天一共做了多少次",
      "combo": "none"
    },
    {
      "index": 5,
      "scene": "农场养殖与种植",
      "angle": "已知原有牲畜数量和新增数量（需进位），求现在的总头数",
      "combo": "none"
    },
    {
      "index": 6,
      "scene": "动物观察与保护",
      "angle": "已知鸟群总数和飞走的数量（需退位），求树上还剩多少只鸟",
      "combo": "none"
    },
    {
      "index": 7,
      "scene": "资源与环保统计",
      "angle": "已知回收瓶子的整十数和零头数，求一共回收了多少个瓶子",
      "combo": "none"
    },
    {
      "index": 8,
      "scene": "体育比赛计分",
      "angle": "比较两支队伍上半场和下半场的得分总和，判断哪队总分更高",
      "combo": "none"
    },
    {
      "index": 9,
      "scene": "公平游戏与概率",
      "angle": "掷骰子游戏中某次未得分（得0分），结合之前分数求当前累计总分",
      "combo": "none"
    },
    {
      "index": 10,
      "scene": "校园活动组织",
      "angle": "将9名同学分成两组进行比赛，已知一组人数，求另一组有几人",
      "combo": "none"
    }
  ]
}
